import{_ as l,W as i,s as o,u as p,I as n,ah as u,w as s,Z as e,A as r}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const T=JSON.parse('{"title":"使用这个开源的会计应用来管理你的小企业 | LCTT x X-CMD","titleTemplate":false,"description":"使用这个开源的会计应用来管理你的小企业 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"使用这个开源的会计应用来管理你的小企业 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用这个开源的会计应用来管理你的小企业 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230327.2 ⭐️ Use this open source accounting app to run your small business","title":"使用这个开源的会计应用来管理你的小企业","tag":"202304"},"relativePath":"202304/20230327.2 ⭐️ Use this open source accounting app to run your small business.md","filePath":"[post].md"}'),d={name:"202304/20230327.2 ⭐️ Use this open source accounting app to run your small business.md"};function b(h,t,m,g,C,f){const a=i("Link");return p(),o("div",null,[t[22]||(t[22]=n("h1",{id:"使用这个开源的会计应用来管理你的小企业",tabindex:"-1"},[s("使用这个开源的会计应用来管理你的小企业 "),n("a",{class:"header-anchor",href:"#使用这个开源的会计应用来管理你的小企业","aria-label":"Permalink to 使用这个开源的会计应用来管理你的小企业"},"​")],-1)),t[23]||(t[23]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/08/150133rfxheuuce1ufi99c.jpg",alt:""})],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,"用 GnuCash 跟踪客户和发票的情况。")],-1)),n("p",null,[e(a,{href:"https://www.gnucash.org/"},{default:r(()=>t[0]||(t[0]=[s("GnuCash")])),_:1}),t[1]||(t[1]=s(" 是一个强大而灵活的会计工具，可用于小企业的发票和会计。它的许多功能使它特别适合这一目的，包括跟踪支出和收入、生成报告和管理发票的能力。此外，GnuCash 是自由开源的，这使得资源有限的小企业也可以使用它。在这篇文章中，我会讨论 GnuCash 的特点，使你可以很容易地在自己的小企业中开始使用它。"))]),t[25]||(t[25]=u('<p>几年前，我开始使用 GnuCash 进行个人财务管理，但发现它也可以作为我的小企业的一个有用工具。在我企业的大部分时间里，我一直在使用一个专有的解决方案。我逐渐厌倦了被迫定期升级以获取我的小企业的发票和报表。转而使用 GnuCash，使我能够在不牺牲任何功能的情况下，将我的小企业会计与我的个人财务相结合。</p><h3 id="在-linux-上安装-gnucash" tabindex="-1">在 Linux 上安装 GnuCash <a class="header-anchor" href="#在-linux-上安装-gnucash" aria-label="Permalink to 在 Linux 上安装 GnuCash">​</a></h3><p>你可以从你的仓库中安装 GnuCash。在 Debian、Elementary 和类似的软件上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo apt install gnucash</span></span></code></pre></div><p>在 Fedora、CentOS、Mageia 和类似系统上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install gnucash</span></span></code></pre></div><h3 id="企业版-gnucash" tabindex="-1">企业版 GnuCash <a class="header-anchor" href="#企业版-gnucash" aria-label="Permalink to 企业版 GnuCash">​</a></h3><p>GnuCash 带有一个账户设置向导，可以帮助你建立一个普通的商业账户配置。要访问它：</p><ul><li>启动 GnuCash。</li><li>点击 “<ruby>文件<rt>File</rt></ruby>” 菜单，选择 “<ruby>新文件<rt>New File</rt></ruby>”。</li></ul><p>按照屏幕上出现的 GnuCash 助手来创建你的新商业账户文件。</p><p>屏幕上的说明将指导你完成设置业务的过程。单击 “<ruby>助手<rt>Assistant</rt></ruby>” 窗口右上角的 “<ruby>下一步<rt>Next</rt></ruby>”。系统会提示你输入公司名称、地址、联系信息和你自己选择的公司 ID。你还必须选择默认税表和日期格式。</p><p>下一个页面提示你选择货币，有大量的货币支持。</p>',12)),n("p",null,[t[3]||(t[3]=s("然后提示你选择你要创建的账户。选择创建 “")),t[4]||(t[4]=n("ruby",null,[s("企业账户"),n("rt",null,"Business Accounts")],-1)),t[5]||(t[5]=s("” 的选项。你可以随时定制账户列表，GnuCash 提供了 ")),e(a,{href:"https://www.gnucash.org/docs/v4/C/gnucash-guide/bus_setup.html"},{default:r(()=>t[2]||(t[2]=[s("大量的文档")])),_:1}),t[6]||(t[6]=s("，帮助你更好地根据个人需求进行定制。"))]),t[26]||(t[26]=u('<p>完成助手，然后单击 GnuCash “助手” 窗口右上角的 “<ruby>应用<rt>Apply</rt></ruby>”。</p><h3 id="添加客户" tabindex="-1">添加客户 <a class="header-anchor" href="#添加客户" aria-label="Permalink to 添加客户">​</a></h3><p>GnuCash 的顶部菜单有一个标有 “<ruby>业务<rt>Business</rt></ruby>” 的菜单项。该菜单上的第一个项目是 “<ruby>客户<rt>Customers</rt></ruby>”，其次是 “<ruby>客户概览<rt>Customers Overview</rt></ruby>”。在这里你可以查看你所有客户的列表。</p><p>下一个项目是 “<ruby>新客户<rt>New Customer</rt></ruby>”。这是你输入新客户的地方。对话框为客户信息提供了一个位置，包括帐单信息、运输地址、电子邮件地址、电话号码等。</p><h3 id="创建一个发票" tabindex="-1">创建一个发票 <a class="header-anchor" href="#创建一个发票" aria-label="Permalink to 创建一个发票">​</a></h3><p>添加客户后，你可以开始创建发票的过程。点击 “业务” 菜单，选择 “客户”，然后点击 “<ruby>新发票<rt>New Invoice</rt></ruby>”。</p><p>付款处理也很简单。这位于 “业务” 菜单中。选择 “客户”，然后 “<ruby>处理付款<rt>Process Payment</rt></ruby>”。</p><h3 id="你在做生意了" tabindex="-1">你在做生意了 <a class="header-anchor" href="#你在做生意了" aria-label="Permalink to 你在做生意了">​</a></h3><p>如果你的业务需要，“业务” 菜单还包括输入供应商和雇员的选项。有一个菜单项用于销售税和许多其他选项，以确保你符合当地的要求。</p><p>使用 GnuCash，你的数据不是以专有格式存储的，所以如果你需要，你可以在将来迁移到任何其他平台。数据存储的开放标准，特别是当这些数据是法律要求的时候，是很重要的，可以让你完全拥有你的商业历史。使用 GnuCash 使你能控制你的小企业。</p><hr>',11)),n("p",null,[t[8]||(t[8]=s("via: ")),e(a,{href:"https://opensource.com/article/23/3/open-source-accounting-run-business"},{default:r(()=>t[7]||(t[7]=[s("https://opensource.com/article/23/3/open-source-accounting-run-business")])),_:1})]),n("p",null,[t[13]||(t[13]=s("作者：")),e(a,{href:"https://opensource.com/users/don-watkins"},{default:r(()=>t[9]||(t[9]=[s("Don Watkins")])),_:1}),t[14]||(t[14]=s(" 选题：")),e(a,{href:"https://github.com/lkxed/"},{default:r(()=>t[10]||(t[10]=[s("lkxed")])),_:1}),t[15]||(t[15]=s(" 译者：")),e(a,{href:"https://github.com/geekpi"},{default:r(()=>t[11]||(t[11]=[s("geekpi")])),_:1}),t[16]||(t[16]=s(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:r(()=>t[12]||(t[12]=[s("wxy")])),_:1})]),n("p",null,[t[19]||(t[19]=s("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>t[17]||(t[17]=[s("LCTT")])),_:1}),t[20]||(t[20]=s(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:r(()=>t[18]||(t[18]=[s("Linux中国")])),_:1}),t[21]||(t[21]=s(" 荣誉推出"))])])}const k=l(d,[["render",b]]);export{T as __pageData,k as default};
